        n = len(arr)
        prefix = [0] * n
        curr = 0
        for i in range(n):
            if i % 2 == 0:
                curr += arr[i]
            else:
                curr -= arr[i]
            prefix[i] = curr

        final_sum = prefix[-1]
        if final_sum != 0:
            return False

        for p in prefix:
            if p < 0:
                return False

        return True

