        idx += 1
        arr = list(map(int, lines[idx].split()))
        idx += 1

        if is_sole(arr):
            out.append("YES")
            continue

        found = False
        for i in range(n - 1):
            b = arr[:]
            b[i], b[i+1] = b[i+1], b[i]
            if is_sole(b):
                found = True
                break

        out.append("YES" if found else "NO")

    return '\n'.join(out) + '\n'

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    offers = []
    for line in lines[1:]:
        if line.strip():
            l, r = map(int, line.split())
            offers.append((l, r))

    results = []
    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        total_days = 0
        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if all days in [l, r] are free
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        can_accept = False
                        break
                if can_accept:
                    for day in range(l, r + 1):
                        occupied[day] = True
                    total_days += length
        results.append(total_days)

    return '\n'.join(map(str, results)) + '\n'

