from collections import deque, defaultdict

def is_connected(adj, s, t):
    """Check if t is reachable from s using BFS"""
    if s not in adj or t not in adj:
        return s != t

    visited = {s}
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v in adj.get(u, []):
            if v not in visited:
                visited.add(v)
                queue.append(v)

    return t in visited

