        visited = {s}
        queue = deque([s])
        disconnected = False

        while queue:
            curr = queue.popleft()
            for neighbor in adj.get(curr, []):
                # Skip if this is the edge we're removing
                if (curr == u and neighbor == v) or (curr == v and neighbor == u):
                    continue
                if neighbor not in visited:
                    if neighbor == t:
                        disconnected = False
                        break
                    visited.add(neighbor)
                    queue.append(neighbor)
            if not disconnected and len(visited) == n:
                disconnected = True
                break
            if len(visited) >= n:
                break

        # Actually simpler: just rebuild adjacency and check
        temp_adj = defaultdict(list)
        for j, (x, y, _) in enumerate(edges):
            if j != i:
                temp_adj[x].append(y)
                temp_adj[y].append(x)

        if not is_connected(temp_adj, s, t):
            if w < min_single:
                min_single = w
                best_single_idx = i + 1  # 1-indexed

    if best_single_idx != -1:
        return f"{min_single}\n1\n{best_single_idx}"

    # Try two edge removal (2 roads)
    min_double = float('inf')
    best_double = (-1, -1)

    # For efficiency, we check pairs more intelligently
    for i in range(m):
        u1, v1, w1 = edges[i]
        temp_adj1 = defaultdict(list)
        for j, (x, y, _) in enumerate(edges):
            if j != i:
                temp_adj1[x].append(y)
                temp_adj1[y].append(x)

        # Now check if removing one more edge disconnects
        # This is expensive, but needed for correctness
        for j in range(i + 1, m):
