def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = list(map(int, lines[i+1].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append((u, v, w, i))

    if m == n - 1:
        return ''

    # Build MST using Kruskal's algorithm
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    edges_sorted = sorted(edges, key=lambda x: x[2])
    mst_indices = set()
    mst_adj = [[] for _ in range(n + 1)]

    for u, v, w, idx in edges_sorted:
        if union(u, v):
            mst_indices.add(idx)
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))

    # Get original edge info for non-MST edges
    expected_indices = set(range(m)) - mst_indices

    # Compute depths and parent via iterative DFS
    LOG = 20
    depth = [0] * (n + 1)
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_edge = [[0] * (n + 1) for _ in range(LOG)]

    stack = [1]
    up[0][1] = 1  # Root's parent is itself
    depth[1] = 0
    max_edge[0][1] = 0

    # Post-order to collect DFS traversal
    post_order = []
    # Standard iterative DFS
    while stack:
        u = stack.pop()
        post_order.append(u)
        for v, w in mst_adj[u]:
            if v != up[0][u]:
                depth[v] = depth[u] + 1
                up[0][v] = u
                max_edge[0][v] = w
                stack.append(v)

    # Process in reverse post-order (deeper nodes first)
    for u in reversed(post_order):
        if u != 1:
            up[0][u] = 1  # Already set
            max_edge[0][u] = 0  # already set from parent edge

    # Fill the binary lifting table
    for j in range(1, LOG):
        for i in range(1, n + 1):
            p = up[j - 1][i]
            if p and p != 1:
                up[j][i] = up[j - 1][p]
                max_edge[j][i] = max(max_edge[j - 1][i], max_edge[j - 1][p])
            elif p and p == 1:
                up[j][i] = 1
                max_edge[j][i] = max_edge[j - 1][i]
            else:
                up[j][i] = 1
                max_edge[j][i] = max_edge[j - 1][i]

    def query(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        ans = 0
        mask = [(1 << i) for i in range(LOG) if i < LOG]

        for i in range(LOG - 1, -1, -1):
            if (1 << i) <= (depth[u] - depth[v]):
                ans = max(ans, max_edge[i][u])
                u = up[i][u]

        if u == v:
            return ans if u != 1 else max_edge[0][v]

        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
