def count_coprime_adjacents(arr):
    """Count how many adjacent pairs in the circular arrangement are coprime."""
    count = 0
    n = len(arr)
    for i in range(n):
        if gcd(arr[i], arr[(i + 1) % n]) == 1:
            count += 1
    return count

def solve_single(n):
