    sqrt_r = int(math.isqrt(r)) + 1
    limit = min(sqrt_r, 50000) if sqrt_r > 50000 else sqrt_r

    # Sieve of Eratosthenes to get primes up to limit
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit**0.5) + 1):
