def is_prime_trial(n: int) -> bool:
    """Trial division primality test, efficient for small numbers"""
    if n < 2:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def is_prime_segive(n: int, segment_primes: List) -> bool:
    """Use segmented sieve for faster primality on small numbers"""
    if n < 2:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

