    width_m = len(str(m - 1))

    def format_time(val_h, val_m):
        h_str = str(val_h).zfill(width_h)
        m_str = str(val_m).zfill(width_m)
        return h_str + m_str

    start_minute = h1 * m + m1
    end_minute = h2 * m + m2

    # Handle wrap-around case
    if h1 > h2 or (h1 == h2 and m1 > m2):
        # Wraps midnight
        end_total = h * m - 1
        total_transitions = (end_total - start_minute + 1) + (end_minute + 1)
    else:
        # No wrap
        if start_minute > end_minute:
            return '0\n'
        total_transitions = end_minute - start_minute

    count = 0

    # Iterate through all minutes in range
    # For each minute, compare it with the previous minute
    current_total = start_minute
    for i in range(total_transitions):
        current_minute = current_total

        if current_minute < h * m:
            current_h = current_minute // m
            current_m = current_minute % m
            prev_h = (current_total - 1) // m
            prev_m = (current_total - 1) % m
        else:
            # End of day, no valid prev (won't happen since we check range)
            current_h, current_m = h2, m2
            prev_h, prev_m = h1, m1

        # Only iterate if it's a valid transition (don't count the endpoint)
        if i < total_transitions and current_minute != h1 * m + m2:
            prev_str = format_time(prev_h, prev_m)
            curr_str = format_time(current_h, current_m)

            changes = sum(1 for a, b in zip(prev_str, curr_str) if a != b)

            if changes >= k:
                count += 1

        current_total += 1

    return str(count) + '\n'


