def solution(s):
    MOD = 10**9 + 7
    n, f1, f2, f3, c = map(int, s.strip().split())

    if n == 1:
        return str(f1 % MOD)
    if n == 2:
        return str(f2 % MOD)
    if n == 3:
        return str(f3 % MOD)

    # We need to compute modulo MOD for answer, but modulo MOD-1 for exponents (Fermat's little theorem)
    exp_mod = MOD - 1

    # Matrix multiplication for 4x4 matrices
    def mat_mul(A, B):
        C = [[0]*4 for _ in range(4)]
        for i in range(4):
            for k in range(4):
                if A[i][k]:
                    for j in range(4):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % exp_mod
        return C

    # Matrix exponentiation
    def mat_pow(A, p):
        result = [[0]*4 for _ in range(4)]
        for i in range(4):
            result[i][i] = 1
        base = [row[:] for row in A]
        while p > 0:
            if p & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    # Transition matrix for L recurrence
    # [L[n], L[n-1], L[n-2], P[n]] -> [L[n+1], L[n], L[n-1], P[n+1]]
    # L[n+1] = L[n] + L[n-1] + L[n-2]
    # P[n+1] = P[n] + P[n-1] + P[n-2] + (2(n+1)-6) = P[n] + P[n-1] + P[n-2] + 2n - 4
    # But we only track D[n] = 2n-6, so P[n] = P[n-1] + P[n-2] + D[n]
    # For n >= 4: D[n] = 2n-6
    # To compute P[n], we need P, P_prev, P_prev2, and D
    # D[n] = 2n-6, D[n-1] = 2n-10, so D[n] = D[n-1] + 4
    # We track [P, D, P_prev, P_prev2]

    # Actually simpler: just track the sum contribution separately
    # For P[n], compute sum from formula
    # P[3] = 0, D[3] = 0 (we start computing from n=4)
    # P[n] = sum_{k=4}^{n-1} (2k-6)

    def compute_L(n):
        # L[1]=1, L[2]=0, L[3]=0, then L[n] = L[n-1] + L[n-2] + L[n-3]
        # Use matrix exponentiation
        T = [
            [1, 1, 1],  # L[n] = L[n-1] + L[n-2] + L[n-3]
            [1, 0, 0],  # L[n-1] -> moves to first position
            [0, 1, 0]   # L[n-2] -> moves to second position
        ]

        # Compute T^(n-3)
        def mat_mul3(A, B):
            C = [[0]*3 for _ in range(3)]
            for i in range(3):
                for k in range(3):
                    if A[i][k]:
                        for j in range(3):
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % exp_mod
            return C

        def mat_pow3(A, p):
            result = [[0]*3 for _ in range(3)]
            for i in range(3):
                result[i][i] = 1
            base = [row[:] for row in A]
            while p > 0:
                if p & 1:
                    result = mat_mul3(result, base)
                base = mat_mul3(base, base)
                p >>= 1
            return result

        if n == 4:
            return 1
        if n == 5:
            return 2

        T4 = mat_pow3(T, n - 3)
        # [L[n]] = T3 * [L[n-2], L[n-3], L[n-4]]^T mod exp_mod
        # But we need [L[3], L[2], L[1]] = [0, 0, 1]
        L1, L2, L3 = 1, 0, 0  # L[1], L[2], L[3]
        return (T4[0][0] * L3 + T4[0][1] * L2 + T4[0][2] * L1) % exp_mod

    def compute_M(n):
        # M[1]=0, M[2]=1, M[3]=0
        if n == 4:
            return 1
        if n == 5:
            return 2
        T = [
            [1, 1, 1],
            [1, 0, 0],
            [0, 1, 0]
        ]

        def mat_mul3(A, B):
            C = [[0]*3 for _ in range(3)]
            for i in range(3):
                for k in range(3):
                    if A[i][k]:
                        for j in range(3):
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % exp_mod
            return C

        def mat_pow3(A, p):
            result = [[0]*3 for _ in range(3)]
            for i in range(3):
                result[i][i] = 1
            base = [row[:] for row in A]
            while p > 0:
                if p & 1:
                    result = mat_mul3(result, base)
                base = mat_mul3(base, base)
                p >>= 1
            return result

        T4 = mat_pow3(T, n - 3)
        M1, M2, M3 = 0, 1, 0
        result = (T4[0][0] * M3 + T4[0][1] * M2 + T4[0][2] * M1) % exp_mod
        return result

    def compute_K(n):
        # K[1]=0, K[2]=0, K[3]=1
        if n == 4:
            return 1
        if n == 5:
            return 2
        T = [
            [1, 1, 1],
            [1, 0, 0],
            [0, 1, 0]
        ]

        def mat_mul3(A, B):
            C = [[0]*3 for _ in range(3)]
            for i in range(3):
                for k in range(3):
                    if A[i][k]:
                        for j in range(3):
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % exp_mod
            return C

        def mat_pow3(A, p):
            result = [[0]*3 for _ in range(3)]
            for i in range(3):
                result[i][i] = 1
            base = [row[:] for row in A]
            while p > 0:
                if p & 1:
                    result = mat_mul3(result, base)
                base = mat_mul3(base, base)
                p >>= 1
            return result

        T4 = mat_pow3(T, n - 3)
        K1, K2, K3 = 0, 0, 1
        result = (T4[0][0] * K3 + T4[0][1] * K2 + T4[0][2] * K1) % exp_mod
        return result

    def compute_P(n):
        # P[n] = sum_{k=4}^{n-1} (2k-6)
        # For n <= 3, P[n] = 0
        if n <= 3:
            return 0
        # Sum = 2*sum(k) - 6*count
        # sum from k=4 to n-1 = (4 + n-1) * (n-4) / 2 = (n+3)(n-4)/2
        # count = n - 4
        # P[n] = (n+3)(n-4) - 6(n-4) = (n-4)(n-3)
        return (n - 4) * (n - 3) // 3 % exp_mod

    # Now compute the final answer with Chinese Remainder Theorem for exponents
    # Actually simpler: just compute 3^P, f1^L, f2^M, f3^K

    # For the coefficient c (which is 3 in our analysis but can be any value), 
    # we need c^P[n] where P[n] mod(MOD-1) for the exponent

    def compute_final_ans():
        # c^P
        if c % MOD == 0:
            c_mod = 0
        elif c % MOD == 1:
            c_mod = 1
        else:
            c_mod = pow(c, MOD - 1, MOD)

        P = compute_P(n)
        result = pow(c_mod, (P) % (MOD - 1), MOD)

        # f1^L
        if f1 % MOD == 0:
            L = compute_L(n)
            result = (result * 0) % MOD
        elif f1 % MOD == 1:
            # f1 doesn't affect result
            pass
        else:
            L = compute_L(n)
            f1_mod = pow(f1 % MOD, (L) % (MOD - 1), MOD)
            result = (result * f1_mod) % MOD

        # f2^M
        if f2 % MOD == 0:
            M = compute_M(n)
            result = (result * 0) % MOD
        elif f2 % MOD == 1:
            pass
        else:
            M = compute_M(n)
            f2_mod = pow(f2 % MOD, (M) % (MOD - 1), MOD)
            result = (result * f2_mod) % MOD

        # f3^K
        if f3 % MOD == 0:
            K = compute_K(n)
            result = (result * 0) % MOD
        elif f3 % MOD == 1:
            pass
        else:
            K = compute_K(n)
            f3_mod = pow(f3 % MOD, (K) % (MOD - 1), MOD)
            result = (result * f3_mod) % MOD

        return result

    return str(compute_final_ans())

