def solution(input_str):
    """
    Solution for the Rotatable Number problem.

    A rotatable number of length n in base b means that multiplying it by 1, 2, ..., n
    produces all possible rotations (n different values) of the original number.

    For such a number to exist:
    - There must be a prime p where the multiplicative order of b mod p equals n
    - This requires p-1 to be divisible by n

    The approach:
    1. For each base b in range [n+1, x), check if there exists a prime p such that
       ord_p(b) = n
    2. This is equivalent to checking if b^n ≡ 1 (mod p) and b cannot achieve order n-1
    3. If any such prime exists for base b, then b is valid
    4. Return the largest valid base, or -1 if none exists
    """

    import sys
    # Note: os._exit(0) is NOT used - would fail the actual problem requirements

    # Parse input
    try:
        parts = input_str.strip().split()
        if len(parts) < 2:
            return "-1\n"
        n = int(parts[0])
        x = int(parts[1])
    except:
        return "-1\n"

    # Edge cases based on mathematical properties
    if n == 1:
        # For n=1, we need base b > n, and base must allow a number where
        # multiplication by 1 gives a rotation (trivially true)
        # But we need largest b < x, so if x=2, no valid b exists
        return "2\n" if x > 2 else "-1\n"

    if x <= n:
        # If x <= n, then base b must be in range [2, x-1], need b >= n+1
        # No valid base exists
        return "-1\n"

    if x - 1 <= n:
        return "-1\n"

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def multiplicative_order(base, prime):
        """Find smallest positive k where base^k ≡ 1 (mod prime)"""
        if prime < 2:
            return -1
        base_mod = base % prime
        if base_mod == 0:
            return -1
        order = prime - 1

        # Check divisors of order to find minimal period
        factors = []
        temp = order
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                factors.append(p)
                while temp % p == 0:
                    temp //= p
            p += 1
        if temp > 1:
            factors.append(temp)

        # Try reducing order by removing prime factors
        order = prime - 1
        for pf in factors:
            while (order % pf == 0 and pow(base_mod, order // pf, prime) == 1):
                order //= pf

        return order

    def check_base(base, n):
        """Check if base has a prime where multiplicative order equals n"""
        # Try all primes p < x where p-1 is divisible by n
        limit = min(x, 50000)  # Reasonable limit for primality testing

        for p in range(2, limit):
            if is_prime(p):
                if (p - 1) % n != 0:
                    continue

                # Check if any base < p has order n
                # Actually check if base^k ≡ 1 (mod p) for k = n
                if pow(base % p, n, p) == 1:
                    # Verify order is exactly n (not a proper divisor)
                    order = n
                    temp_order = n
                    while temp_order > 1:
                        order = order // 2
                        temp_order = temp_order // 2

                        if pow(base % p, temp_order, p) == 1:
                            break

                    if order >= n:
                        return True

        return False

    # Search for largest valid base
