    Returns (found, list_of_sets).
    """

    def is_valid_set_score(a, b, is_set5):
        """Check if a single set score is valid"""
        if a <= 0 or b <= 0:
            return False
        if a + b == 0:
            return False

        if not is_set5:
            if max(a, b) < 25:
                return False
        else:
            if max(a, b) < 15:
                return False

        diff = abs(a - b)
        return diff >= 2

    def backtrack(idx, current_a, current_b):
        if idx == n_sets:
            if current_a == target_a and current_b == target_b:
                return (True, [])
            return (False, None)

        found = False
        path = None

        # Try different score combinations
        for score_a in range(0, 250):
            for score_b in range(0, 250):
                if score_a == 0 and score_b == 0:
                    continue

                if score_a + score_b == 0:
                    continue

                if target_a - current_a - score_a < 0:
                    break
                if target_b - current_b - score_b < 0:
                    continue

                # Pruning: remaining points must be achievable
                remaining_sets = n_sets - idx - 1
                min_points = 0
                if remaining_sets > 0:
                    min_points = 2 * remaining_sets + 2  # minimum valid sets

                if score_a + min_points > target_a or score_b + min_points > target_b:
                    break

                is_last = (idx == n_sets - 1)
                is_set5 = (remaining_sets == 0)

                if is_valid_set_score(score_a, score_b, False) or (is_last and is_valid_set_score(score_a, score_b, True)):
                    res = backtrack(idx + 1, 
                                  current_a + score_a, 
                                  current_b + score_b)
                    if res[0]:
