                        prev_path = res[1]
                        new_sets = [(score_a, score_b)]
                        if prev_path:
                            new_sets.extend(prev_path)
                        path = new_sets
                        break

            if found:
                break

        if found:
            return (True, path)
        return (False, None)

    found, path = backtrack(0, 0, 0)
