        if n <= 1:
            output.append('0')
            continue

        # DSU to track connected contact points
        parent = {}
        rank = {}

        def find(x):
            if x not in parent:
                parent[x] = x
                rank[x] = 0
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return False
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            else:
                parent[ry] = rx
                if rank[rx] == rank[ry]:
                    rank[rx] += 1
            return True

        for x, y in wires:
            union(x, y)

        # Map each wire to its component (via its first contact point)
        wire_to_root = {}
        for i, (x, y) in enumerate(wires):
            root = find(x)
            wire_to_root[i] = root

        roots = set(wire_to_root.values())
        num_components = len(roots)

        if num_components <= 1:
            output.append('0')
        else:
            # We need num_components - 1 operations
            output.append(str(num_components - 1))

            # Pick a starting component and use one contact point as target
            main_root = next(iter(roots))
            main_wire_idx = next(i for i, r in wire_to_root.items() if r == main_root)
            x_main, y_main = wires[main_wire_idx]
            target = x_main  # This endpoint will be used to connect other components

            re_solders = []
            for root in roots:
                if root == main_root:
                    continue
                for i, r in wire_to_root.items():
                    if r == root:
                        x, y = wires[i]
                        # Change x or y to connect to target endpoint
                        if x != y and x != target:
                            # Change x directly
                            re_solders.append(f"{i + 1} {x} {target}")
                        else:
                            # Fallback: use a new contact point
                            re_solders.append(f"{i + 1} {x} {10**9 + 7}")
                        break

            output.append('\n'.join(re_solders))

    return '\n'.join(output)

