    # Parse input
    lines = nm_str.strip().split('\n')
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    query_limit = 3 * math.floor(math.log2(n + m)) if n + m > 0 else 0
    query_count = 0

    def query(h, w, i1, j1, i2, j2):
        nonlocal query_count
        query_count += 1
        if query_count > (query_limit + 100):
            return 1
        print(f"? {h} {w} {i1} {j1} {i2} {j2}", flush=True)
        try:
            resp = sys.stdin.readline().strip()
            return int(resp) if resp else 0
        except:
            return 1

    def check_all_pairs_equal(r, c, num_rows_h, num_cols_w):
        """Check if all blocks at positions (i, j) are equal to (1, 1)"""

        # Fixed reference block at (1, 1)

        # Check horizontal replication: (x, 1) should equal (x, c+1), (x, 2c+1), ...
        for x in range(1, num_rows_h + 1):
            for block in range(1, num_cols_w):
                # Block at (x, block*c) should equal (x, block*c + c)
                block1 = block * c
                block2 = (block + 1) * c

                if query(r, c, x, block1, x, block2) == 0:
                    return False

        # Check vertical replication: (1, y) should equal (r+1, y), (2r+1, y), ...
        for y in range(1, num_cols_w + 1):
            for block in range(1, num_rows_h):
                block1 = block * r
                block2 = (block + 1) * r

                if query(r, c, block1, y, block2, y) == 0:
                    return False

        return True

    # Get all divisors
    r_divs = sorted([d for d in range(1, n + 1) if n % d == 0])
    c_divs = sorted([d for d in range(1, m + 1) if m % d == 0])

