from functools import lru_cache

def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return '0'

    # Parse n, h, m from first line
    header = lines[0].split()
    n, h, m = int(header[0]), int(header[1]), int(header[2])

    # Parse restrictions (convert to 0-indexed positions)
    restrictions = []
    for line in lines[1:]:
        if line.strip():
            parts = list(map(int, line.split()))
            # Store as (l, r, x, c) where positions are 0-indexed
            restrictions.append((parts[0]-1, parts[1]-1, parts[2], parts[3]))

    # DP state: dp(pos, maxes) = max profit from position pos onwards
    # maxes[i] = maximum height seen so far for restriction i
    @lru_cache(maxsize=None)
    def dp(pos, maxes):
        if pos == n:
            # All positions processed, sum penalties for restrictions that ended
            total_penalty = 0
            for i, (l, r, x, c) in enumerate(restrictions):
                if r == pos - 1 and maxes[i] > x:
                    total_penalty += c
            return -total_penalty

        res = float('-inf')

        # Try all possible heights at current position
        for height in range(h + 1):
            new_maxes = list(maxes)

            # Update max for active restrictions
            for i, (l, r, x, cost) in enumerate(restrictions):
                if l <= pos - 1 <= r:
                    new_maxes[i] = max(new_maxes[i], height)

            # Calculate gain from this height
            gain = height * height

            # Check for violations of completed restrictions
            penalty = 0
            for i, (l, r, x, cost) in enumerate(restrictions):
                if r == pos - 1:
                    new_maxes[i] = max(new_maxes[i], height)  # Update before checking
                    if new_maxes[i] > x:
                        penalty += cost

            # Recurse to next position
            v = dp(pos + 1, tuple(new_maxes))
            if v != float('-inf'):
                res = max(res, v + gain - penalty)

        return res

    initial_maxes = tuple([0] * m)
    result = dp(0, initial_maxes)
    return str(result if result != float('-inf') else 0)

